import numpy as np, itertools
def load(f):
    lines=open(f).read().splitlines(); n=int(lines[0]); els=[];P=[]
    for ln in lines[2:2+n]:
        s=ln.split(); els.append(s[0]); P.append([float(x) for x in s[1:4]])
    return els, np.array(P)
els,P = load('mol_relaxed.xyz')
n=len(els)
def d(a,b): return float(np.linalg.norm(P[a]-P[b]))
# C5Me5 substituent: ring carbons are indices 92..96 (added sequentially after methyl C88 + its H's)
ring=[92,93,94,95,96]
print("ring bonds:")
for a,b in itertools.combinations(ring,2):
    dd=d(a,b)
    if dd<1.8: print(f"  {a}-{b}: {dd:.3f}")
print("methyl neighbors of each ring carbon:")
for r in ring:
    nb=[(j,round(d(r,j),2)) for j in range(n) if els[j]=='C' and j!=r and 1.4<d(r,j)<1.75]
    print(f"  C{r}: {nb}")
# check ipso carbon hybridization: which ring C is bonded to C84 (1.526) -> C92
# Ga-Cp ring carbons sanity for one Cp*Ga unit (Ga1, ring 2-6)
print("Ga1-CpC distances:", [round(d(1,j),2) for j in range(2,7)])
# verify all hydrogens have a heavy-atom partner within 1.35 A
bad=[]
for i in range(n):
    if els[i]=='H':
        m=min((d(i,j) for j in range(n) if els[j]!='H'), default=9)
        if m>1.35: bad.append((i,round(m,2)))
print("orphan H:", bad if bad else "none")
# Ni coordination: all heavy atoms within 2.7 of Ni
print("Ni neighbors <2.7:", [(i,els[i],round(d(0,i),2)) for i in range(1,n) if d(0,i)<2.7])
